// The nginx host configuration (infra/web/) generated from the one URL map (seo/url-migration.mjs).
//
// Pinned: the committed generated files equal a fresh generation (a map change without regeneration fails here);
// nginx's precedence (`=` first, then the LONGEST `^~` prefix) gives the same answer as newPath() (first rule wins)
// for every rule, every path under every prefix and every sitemap URL — and the generator REFUSES a map where it
// would not; the /?country= map holds exactly the countries with a page, behind a two-letter gate; site.conf types
// no path redirect of its own, keeps Pages' headers (no HSTS / X-Frame-Options / header CSP), answers 404 with
// 404.html; the two workflows are pinned, credential-free (web-server.yml) and gated off (deploy-web.yml).
// Each rule's FIRST assertion proves it fires. The live behaviour is proven by infra/web/test/run.sh (Docker).

import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, mkdtempSync, writeFileSync, rmSync, cpSync, mkdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';
import { RULES, newPath } from './url-migration.mjs';
import {
  generate, staleFiles, nginxNewPath, disagreements, probePaths, redirectsConf, countryMapConf, sitemapPaths,
  OUT_DIR, REDIRECTS_FILE, COUNTRY_MAP_FILE,
} from '../scripts/build-web-server-config.mjs';
import { servedBy, siteLocation, pathsToAsk } from '../scripts/verify-web-redirects.mjs';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const read = (...p) => readFileSync(join(ROOT, ...p), 'utf8');
const code = (text) => text.split('\n').filter((l) => !/^\s*#/.test(l)).join('\n');

test('the committed generated files equal a fresh generation; a stale one is caught', () => {
  const tmp = mkdtempSync(join(tmpdir(), 'web-conf-'));
  try {
    cpSync(OUT_DIR, tmp, { recursive: true });
    writeFileSync(join(tmp, REDIRECTS_FILE), `${readFileSync(join(tmp, REDIRECTS_FILE), 'utf8')}# hand edit\n`);
    assert.deepEqual(staleFiles(ROOT, tmp), [REDIRECTS_FILE], 'the proof: a changed file is stale');
  } finally { rmSync(tmp, { recursive: true, force: true }); }
  assert.deepEqual(staleFiles(), [], 'run: node scripts/build-web-server-config.mjs');
  const g = generate();
  for (const f of [REDIRECTS_FILE, COUNTRY_MAP_FILE]) assert.match(g[f], /^# GENERATED by scripts\/build-web-server-config\.mjs/);
});

test('one nginx location per rule, in the shape the map names, the query kept', () => {
  const conf = code(read('infra', 'web', 'nginx', REDIRECTS_FILE));
  const locs = conf.split('\n').filter((l) => l.startsWith('location '));
  assert.equal(locs.length, RULES.length, 'the proof: every rule has its line');
  RULES.forEach((r, i) => {
    if (r.type === 'exact') assert.equal(locs[i], `location = ${r.from} { return 301 ${r.to}$is_args$args; }`);
    else {
      assert.equal(locs[i], `location ^~ ${r.from} {`);
      const esc = r.from.replace(/[.]/g, '\\.');
      assert.ok(conf.includes(`location ^~ ${r.from} {\n    rewrite ^${esc}((?:[^/]*/)*[^/.]+)$ ${r.to}$1/ permanent;\n    rewrite ^${esc}(.*)$ ${r.to}$1 permanent;\n}`),
        `${r.from}: the slash-less page rewrite first, then the plain one`);
    }
  });
  assert.doesNotMatch(conf, /\bredirect;|\breturn 302\b|\bif\s*\(/, 'nothing but permanent redirects, no if');
});

test('nginx precedence reproduces newPath() for every rule, every prefix and the whole sitemap', () => {
  // negative controls: first-match vs longest-prefix, and an exact rule caught by an earlier prefix
  const shorterFirst = [{ type: 'prefix', from: '/a/', to: '/x/' }, { type: 'prefix', from: '/a/b/', to: '/y/' }];
  const firstWins = (rules) => (p) => { for (const r of rules) { if (r.type === 'exact' && p === r.from) return r.to; if (r.type === 'prefix' && p.startsWith(r.from)) return r.to + p.slice(r.from.length); } return null; };
  assert.notDeepEqual(disagreements(shorterFirst, probePaths(shorterFirst), firstWins(shorterFirst)), [], 'the proof: a shadowed longer prefix is caught');
  const exactAfter = [{ type: 'prefix', from: '/a/', to: '/x/' }, { type: 'exact', from: '/a/b', to: '/y/' }];
  assert.notDeepEqual(disagreements(exactAfter, probePaths(exactAfter), firstWins(exactAfter)), [], 'an exact rule after a catching prefix is caught');
  // the real map
  const sm = sitemapPaths();
  assert.ok(sm.length > 200, `sitemap read (${sm.length})`);
  const probes = probePaths(RULES, sm);
  assert.deepEqual(disagreements(RULES, probes), []);
  for (const p of sm) assert.equal(nginxNewPath(p), newPath(p), p);
  assert.equal(nginxNewPath('/en/esim/turkey/'), '/destinations/turkey/');
  assert.equal(nginxNewPath('/'), null);
});

test('the generator refuses a map nginx cannot express', () => {
  assert.throws(() => redirectsConf([{ type: 'exact', from: '/', to: '/en/' }], []), /never a rule/);
  assert.throws(() => redirectsConf([{ type: 'prefix', from: '/a', to: '/b/' }], []), /ends with a slash/);
  assert.throws(() => redirectsConf([{ type: 'exact', from: '/a b', to: '/b/' }], []), /not a plain path/);
  assert.throws(() => redirectsConf([{ type: 'exact', from: '/a', to: '/b/' }, { type: 'exact', from: '/a', to: '/c/' }], []), /duplicate/);
  assert.doesNotThrow(() => redirectsConf(RULES, sitemapPaths()));
});

test('/?country=XX maps exactly the countries with a page, behind a two-letter gate (either case)', () => {
  const cc = JSON.parse(read('seo', 'catalogue-countries.json')).countries;
  const conf = code(read('infra', 'web', 'nginx', COUNTRY_MAP_FILE));
  const tr = cc.find((c) => c.iso === 'TR');
  assert.match(conf, new RegExp(`^\\s+TR /ru/esim/${tr.slug}/;$`, 'm'), 'the proof: Turkey');
  const entries = [...conf.matchAll(/^\s+([A-Z]{2}) (\/ru\/esim\/[a-z0-9-]+\/);$/gm)];
  assert.equal(entries.length, cc.length);
  assert.match(conf, /map \$arg_country \$country_code \{\s+default "";\s+"~\*\^\[A-Z\]\{2\}\$" \$arg_country;\s+\}/, 'two-letter gate first (~* = either case, as the old home script)');
  assert.match(conf, /map \$country_code \$country_redirect \{\s+default "";/);
  assert.throws(() => countryMapConf([{ iso: 'tr', slug: 'x' }]), /empty map/);
});

test('site.conf types no page redirect, keeps the Pages headers and answers 404 with 404.html', () => {
  const site = code(read('infra', 'web', 'nginx', 'site.conf'));
  assert.match(site, /include \/srv\/magicesim\/current\/nginx\/redirects\.conf;/, 'the proof: the generated rules are included');
  assert.match(site, /include \/srv\/magicesim\/current\/nginx\/country-map\.conf;/);
  assert.doesNotMatch(site, /\brewrite\b/, 'no hand-typed rewrite');
  const returns = [...site.matchAll(/return 30[1278] ([^;]+);/g)].map((m) => m[1]);
  assert.deepEqual(returns.sort(), ['$country_redirect$country_rest_q', 'https://magicesim.store$request_uri', 'https://magicesim.store$request_uri'].sort());
  assert.doesNotMatch(site, /Strict-Transport-Security|X-Frame-Options|Content-Security-Policy/i, 'owner: Pages-equivalent headers only');
  assert.match(site, /error_page 404 \/404\.html;/);
  assert.match(site, /try_files \$uri \$uri\.html \$uri\/ =404;/);
  assert.match(site, /expires 10m;/, 'Cache-Control: max-age=600 like Pages');
  assert.match(site, /application\/manifest\+json webmanifest/);
  assert.doesNotMatch(site, /\$remote_addr|\$http_accept_language|\$http_user_agent|geoip/i, 'no IP / language / UA logic');
  // nothing else under infra/web/ types a path redirect
  for (const f of ['infra/web/test/compose.yml', 'infra/web/test/conf.d/magicesim.conf', 'infra/web/deploy/activate.sh']) {
    assert.doesNotMatch(read(...f.split('/')), /return 301|rewrite /, f);
  }
});

test('the verifier resolves paths the way Pages does', () => {
  const tmp = mkdtempSync(join(tmpdir(), 'web-served-'));
  try {
    mkdirSync(join(tmp, 'es'), { recursive: true });
    writeFileSync(join(tmp, 'es', 'index.html'), 'x');
    writeFileSync(join(tmp, 'iphone.html'), 'x');
    writeFileSync(join(tmp, '404.html'), 'x');
    assert.equal(servedBy(tmp, '/es/'), 'file:es/index.html', 'the proof');
    assert.equal(servedBy(tmp, '/es'), 'dir-redirect');
    assert.equal(servedBy(tmp, '/iphone'), 'file:iphone.html');
    assert.equal(servedBy(tmp, '/pay/abc'), null);
    assert.equal(servedBy(tmp, '/../etc/passwd'), null);
    assert.deepEqual(pathsToAsk(tmp), ['/es/', '/iphone.html']);
  } finally { rmSync(tmp, { recursive: true, force: true }); }
  assert.equal(siteLocation('https://magicesim.store/ru/esim/x/?a=1', 'https://127.0.0.1:1'), '/ru/esim/x/?a=1');
  assert.equal(siteLocation('/x/', 'https://127.0.0.1:1'), '/x/');
  assert.equal(siteLocation('https://evil.example/x/', 'https://127.0.0.1:1'), null);
});

test('the web workflows: pinned nginx, credential-free proof, deploy gated off and pinned host keys', () => {
  const compose = read('infra', 'web', 'test', 'compose.yml');
  const digest = /image:\s*nginx:stable-alpine@(sha256:[0-9a-f]{64})/.exec(compose);
  assert.ok(digest, 'the proof: nginx pinned by digest');
  const proof = read('.github', 'workflows', 'web-server.yml');
  assert.match(proof, /^on:\n {2}pull_request:\n {4}paths:/m);
  for (const p of ['infra/web/**', 'seo/url-migration.mjs', 'scripts/*web*', 'seo/catalogue-countries.json']) assert.ok(proof.includes(`"${p}"`), p);
  assert.doesNotMatch(code(proof), /secrets\.|matrix:/, 'no secret, no matrix');
  const deploy = code(read('.github', 'workflows', 'deploy-web.yml'));
  const jobIfs = [...deploy.matchAll(/^ {4}if: >-\n\s+(.+)$/gm)].map((m) => m[1]);
  const jobs = [...deploy.matchAll(/^ {2}([a-z][a-z0-9-]*):\n {4}name:/gm)].map((m) => m[1]);
  assert.ok(jobs.length >= 1 && jobIfs.length === jobs.length, `every job has an if (${jobs.length} jobs)`);
  for (const c of jobIfs) assert.match(c, /^vars\.WEB_DEPLOY == 'true' && /, 'every job gated on WEB_DEPLOY');
  assert.doesNotMatch(deploy, /StrictHostKeyChecking[ =](no|accept-new)/i);
  assert.match(deploy, /StrictHostKeyChecking yes/);
  for (const s of ['WEB_SSH_KEY', 'WEB_HOST', 'WEB_KNOWN_HOSTS']) assert.match(deploy, new RegExp(`secrets\\.${s}\\b`));
  assert.match(deploy, /WEB_TEST_STRICT: "1"/, 'a deploy never ships a map whose targets are missing');
  assert.doesNotMatch(deploy, /^\s*(contents|pages|id-token|deployments):\s*write/m, 'no write permission');
});
